const resources: Resource[] = [...part0,...part1,...part2,...part3,...part4,...part5,...part6,...part7,...part8,...part9,...part10,...part11,...part12,...part13,...part14];
// Interleave institutions so the first page represents the whole directory.
const groups = new Map<string, Resource[]>();
for (const r of [...resources, ...turkishResources]) {
 const group = groups.get(r.university) || [];
 group.push(r); groups.set(r.university, group);
}
const combined: Resource[] = [];
for (let i = 0; i < Math.max(...[...groups.values()].map(g => g.length)); i++) {
 for (const group of groups.values()) if (group[i]) combined.push(group[i]);
}
export default combined;
